<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=$_POST['action']??'';if($a==='add'){$db->prepare('INSERT INTO customers(name,phone,address) VALUES(?,?,?)')->execute([trim($_POST['name']),trim($_POST['phone']??''),trim($_POST['address']??'')]);header('Location: customers.php?saved=1');exit;}if($a==='pay'){$cid=(int)$_POST['customer_id'];$amount=(float)$_POST['amount'];if($amount<=0)throw new RuntimeException('Enter a valid payment amount.');$q=$db->prepare("SELECT COALESCE(SUM(total-paid),0) FROM sales WHERE customer_id=? AND payment_method='credit'");$q->execute([$cid]);$due=(float)$q->fetchColumn();if($amount>$due+0.0001)throw new RuntimeException('Payment cannot exceed outstanding credit.');$db->beginTransaction();$remaining=$amount;$q=$db->prepare("SELECT id,total,paid FROM sales WHERE customer_id=? AND payment_method='credit' AND total>paid ORDER BY id");$q->execute([$cid]);foreach($q as $s){$open=(float)$s['total']-(float)$s['paid'];$take=min($remaining,$open);if($take>0){$db->prepare('UPDATE sales SET paid=paid+? WHERE id=?')->execute([$take,$s['id']]);$remaining-=$take;}if($remaining<=0)break;}$db->commit();header('Location: customers.php?paid=1');exit;}}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}$rows=$db->query("SELECT c.*,COALESCE((SELECT SUM(s.total-s.paid) FROM sales s WHERE s.customer_id=c.id AND s.payment_method='credit'),0) due,COALESCE((SELECT SUM(s.total) FROM sales s WHERE s.customer_id=c.id),0) sales_total FROM customers c ORDER BY c.name")->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customers</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">CUSTOMERS</div><h1>Customers</h1><p>Customer directory, credit balances and payments.</p></div></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ Customer added.</div><?php endif;?><?php if(isset($_GET['paid'])):?><div class="success">✓ Customer payment recorded.</div><?php endif;?><section class="panel"><h2>Add Customer</h2><form method="post" class="grid"><input type="hidden" name="action" value="add"><label>Name<input name="name" required></label><label>Phone<input name="phone"></label><label>Address<input name="address"></label><button class="btn">Save Customer</button></form></section><section class="panel"><h2>Customer Balances</h2><table><tr><th>Customer</th><th>Phone</th><th>Total Sales</th><th>Credit Due</th><th>Payment</th></tr><?php foreach($rows as $r):$salesTotal=(float)$r['sales_total'];$due=(float)$r['due'];?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['phone'])?></td><td>Rs. <?=money($salesTotal)?></td><td><b>Rs. <?=money($due)?></b></td><td><?php if($due>0):?><form method="post"><input type="hidden" name="action" value="pay"><input type="hidden" name="customer_id" value="<?=$r['id']?>"><input name="amount" type="number" min="0.01" max="<?=e((string)$due)?>" step="0.01" placeholder="Amount" required><button class="btn">Receive Payment</button></form><?php else:?><span>Clear</span><?php endif;?></td></tr><?php endforeach;?></table></section></main></body></html>